export function getLocalProducts(lang) {
  if (lang === 'fr') return LOCAL_PRODUCTS.filter(p => p.lang === 'fr');
  if (lang === 'en') return LOCAL_PRODUCTS.filter(p => p.lang === 'en');
  return LOCAL_PRODUCTS;
}

export default LOCAL_PRODUCTS;
